import{_ as t,o as r,c as i,ah as a}from"./chunks/framework.BsNNkeaH.js";const p=JSON.parse('{"title":"Frais et tarification","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/frais-tarification.md","filePath":"src/guide/admin/frais-tarification.md"}'),s={name:"guide/admin/frais-tarification.md"};function n(l,e,o,d,c,u){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="frais-et-tarification" tabindex="-1">Frais et tarification <a class="header-anchor" href="#frais-et-tarification" aria-label="Permalink to &quot;Frais et tarification&quot;">​</a></h1><p>Cette section couvre la définition des montants dus par les familles (grilles de frais) et les remises que vous pouvez accorder au cas par cas. L&#39;encaissement des paiements eux-mêmes est le travail quotidien de la caisse — vous n&#39;intervenez ici que sur la tarification et les remises.</p><h2 id="grilles-de-frais" tabindex="-1">Grilles de frais <a class="header-anchor" href="#grilles-de-frais" aria-label="Permalink to &quot;Grilles de frais&quot;">​</a></h2><p><strong>Paramétrage scolaire → Grilles de frais</strong> définit, pour un site, un département et une année scolaire donnés, la liste des frais dus par les élèves de ce département sur ce site et cette année. Un élève sans grille de frais correspondant à son site/département/année n&#39;a aucun montant calculé.</p><p>Pour créer une grille de frais :</p><ol><li>Cliquez sur <strong>Nouvelle grille de frais</strong>.</li><li>Choisissez le <strong>Site</strong>, le <strong>Département</strong> et l&#39;<strong>Année scolaire</strong>.</li><li>Ajoutez un ou plusieurs articles de frais avec <strong>Ajouter un article</strong>, en renseignant pour chacun les champs ci-dessous.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Libellé</td><td>ex. « Frais de scolarité », « Cantine »</td></tr><tr><td>Montant</td><td>—</td></tr><tr><td>Optionnel</td><td>cochez si l&#39;article n&#39;est pas dû par défaut (la famille ou la caisse l&#39;active au cas par cas)</td></tr><tr><td>Catégorie</td><td>Générale, Cantine ou Transport</td></tr></tbody></table><p>Modifier une grille existante permet d&#39;ajouter, changer ou retirer des articles de frais. Supprimer une grille supprime aussi définitivement tous ses articles.</p><h2 id="remises" tabindex="-1">Remises <a class="header-anchor" href="#remises" aria-label="Permalink to &quot;Remises&quot;">​</a></h2><p>Les remises se gèrent non pas sur la grille de frais elle-même, mais sur la facturation d&#39;un élève précis : <strong>Finances → Facturation</strong>, recherchez l&#39;élève, cliquez sur <strong>Voir</strong> pour ouvrir son dossier de facturation.</p><p>Sur cet écran, vous seul (en tant qu&#39;administrateur — la caisse ne peut qu&#39;encaisser des paiements) pouvez accorder ou retirer une remise :</p><p>Pour accorder une remise :</p><ol><li>Dans la section « Remises », renseignez le <strong>Libellé</strong> de la remise.</li><li>Choisissez le <strong>Type</strong> : Montant fixe ou Pourcentage.</li><li>Renseignez la <strong>Valeur</strong> correspondante et, facultativement, un <strong>Motif</strong>.</li><li>Cliquez sur <strong>Accorder la remise</strong>.</li></ol><p>Chaque remise accordée s&#39;affiche avec le nom de l&#39;administrateur qui l&#39;a créée. Le bouton <strong>Retirer cette remise</strong> (dans la liste des remises) la supprime définitivement — le solde dû de l&#39;élève est recalculé immédiatement.</p>',14)])])}const f=t(s,[["render",n]]);export{p as __pageData,f as default};
